potongan kode program berikut! (5 Poin)
Halaman 3 dari 7

public boolean isPalindrome(String s) {
if (s.length() == 0 || s.length == 1) {

return true;
}
if (s.charAt(0) == s.chartAt(s.length() - 1)) {

return isPalindrome(s.substring(1, s.length() - 1));
}
return false;
}

